<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="admin-page-heading"><div><p class="eyebrow">MVP · Research infrastructure</p><h1>Facilities and equipment</h1><p>Maintain laboratories, workshops, specialist facilities, and equipment availability.</p></div><div class="heading-actions"><?php if($canCreate):?><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/facilities/equipment/create">Add equipment</a><a class="button button-primary" href="<?=View::escape($baseUrl)?>admin/facilities/create">Add facility</a><?php endif;?></div></section><?php if(is_string($success)&&$success!==''):?><div class="success-alert"><?=View::escape($success)?></div><?php endif;?><section class="admin-panel"><h2>Facilities</h2><?php if($facilities===[]):?><p class="admin-empty">No facilities are available. A research unit is required first.</p><?php else:?><div class="table-scroll"><table class="admin-table"><thead><tr><th>Facility</th><th>Research unit</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($facilities as$f):?><tr><th><?=View::escape($f['name'])?></th><td><?=View::escape($f['research_unit_name'])?></td><td><?=View::escape(ucwords(str_replace('_',' ',$f['facility_type'])))?></td><td><?=View::escape(ucfirst($f['status']))?></td><td><?php if($canEdit):?><a class="button button-secondary button-compact" href="<?=View::escape($baseUrl)?>admin/facilities/<?=(int)$f['id']?>/edit">Edit</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><section class="admin-panel" id="equipment"><h2>Equipment</h2><?php if($equipment===[]):?><p class="admin-empty">No equipment has been added.</p><?php else:?><div class="table-scroll"><table class="admin-table"><thead><tr><th>Equipment</th><th>Research unit</th><th>Availability</th><th>External use</th><th></th></tr></thead><tbody><?php foreach($equipment as$e):?><tr><th><?=View::escape($e['name'])?><small><?=View::escape(implode(' ',array_filter([$e['manufacturer'],$e['model']])))?></small></th><td><?=View::escape($e['research_unit_name'])?></td><td><?=View::escape(ucfirst($e['availability_status']))?></td><td><?=$e['external_use_allowed']?'Allowed':'Internal only'?></td><td><?php if($canEdit):?><a class="button button-secondary button-compact" href="<?=View::escape($baseUrl)?>admin/facilities/equipment/<?=(int)$e['id']?>/edit">Edit</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
